  function metric(s,key,baseline){const e=s.ext;let n;if(key==='stages')n=num(s.progress.totalStages);else if(key==='zone')n=Math.max(zone(s),num(s.progress.maxZone));else if(key==='kingdom')n=level(s);else if(key==='equipped')n=equipped(s);else if(key==='heroLevel')n=Math.max(1,...s.heroes.map(h=>h.level),num(e.counters.highestLevel));else if(key==='legendEquip')n=(num(e.counters.legendEquip)||s.inventory.some(i=>i.stars>=5))?1:0;else if(key==='enhance15')n=s.inventory.some(i=>i.enhance>=15)?1:0;else if(key==='sixStar')n=s.heroes.some(h=>h.stars===6)?1:0;else if(key==='set4')n=s.heroes.some(h=>{const cnt={};for(const id of Object.values(h.equipment||{})){const i=s.inventory.find(a=>a.id===id);if(i?.set)cnt[i.set]=num(cnt[i.set])+1;}return Object.values(cnt).some(v=>v>=4);})?1:0;else if(key==='ascensions')n=num(s.ascensions);else if(key==='collectionPercent')n=collectionPercent(s);else if(key==='dailyBossKills')n=num(e.counters.dailyBossKills);else if(key==='equipmentKinds')n=num(e.counters.equipmentKinds);else if(key==='loginDays')n=e.weekly.loginDays.length;else if(key==='upgrades')n=num(s.stats.heroLevels);else n=num(s.stats[key]);return Math.max(0,n-num(baseline?.[key]));}
