  function collections(s){const out=[],e=s.ext;for(const [id,kills]of Object.entries(e.collection.monsterKills)){if(!id.startsWith('main:'))continue;[10,50,200,1000].forEach((n,i)=>{const key='monster:'+id+':'+n;out.push({id:key,name:(e.collection.monsterNames?.[id]||id)+' '+n+' 殺',progress:kills,target:n,reward:[{gold:500},{gems:10},{gems:30},{gems:80,tickets:1}][i],claimed:!!e.claimed.collection[key],ready:kills>=n&&!e.claimed.collection[key]});});}CLASS.forEach((c,j)=>[1,5,10,15].forEach((n,i)=>{const id='class:'+c+':'+n;out.push({id,name:CLASS_NAMES[j]+'招募 '+n+' 次',progress:num(e.collection.classRecruits[c]),target:n,reward:{gems:[20,50,100,200][i]},claimed:!!e.claimed.collection[id],ready:num(e.collection.classRecruits[c])>=n&&!e.claimed.collection[id],bonus:'本職業攻擊 +'+[1,2,3,4][i]+'%'});}));[25,50,75,100].forEach((n,i)=>{const id='total:'+n;out.push({id,name:'圖鑑完成 '+n+'%',progress:collectionPercent(s),target:n,reward:[{gems:50},{gems:120},{gems:250},{gems:500,tickets:3}][i],claimed:!!e.claimed.collection[id],ready:collectionPercent(s)>=n&&!e.claimed.collection[id],bonus:'全隊攻擊 +5%'});});return out;}
