    [['books',300,{books:3}],['tickets',250,{tickets:3}],['materials',150,{materials:allMat(5)}],['potions',120,{consumables:{attack:1,gold:1,xp:1}}],['goldBag',200,{consumables:{goldBag:1}},2]].forEach(x=>add('honor:'+x[0],{'books':'技能書 ×3',tickets:'招募券 ×3',materials:'九種素材各 ×5',potions:'靈藥三件套',goldBag:'金幣寶袋'}[x[0]],'honor',{honor:x[1]},x[2],x[3]||1));
    const daily=[['招募券',7500,{tickets:1},1],['生命藥水 ×3',1800,{consumables:{hp:3}},2],['魔力藥水 ×3',1800,{consumables:{mp:3}},2],['九種素材各 ×3',7000,{materials:allMat(3)},2],['攻擊靈藥',12000,{consumables:{attack:1}},1],['智慧靈藥',12000,{consumables:{xp:1}},1],['加速沙漏',8000,{consumables:{hourglass:1}},2],['技能書 ×2',16000,{books:2},2]];
    e.daily.offers.forEach(i=>{const a=daily[i];add('daily:'+i,a[0],'daily',{gold:Math.floor(a[1]*1.15**Math.min(24,level(s)-1)*discount)},a[2],a[3]);});
    [['materials','九種素材各 ×20',1.3,{materials:allMat(20)},5],['rare','虛空／神話各 ×2',.8,{materials:{void:2,myth:2}},5],['books','技能書 ×10',1,{books:10},3],['ticket','招募券',1.2,{tickets:1},3],['badge','傳說徽章碎片',2,{badges:1},1]].forEach(a=>add('weekly:'+a[0],a[1],'weekly',{gold:Math.floor(rate(s)*a[2]*discount)},a[3],a[4]));
