    [['ticket','招募券',40,{tickets:1},3],['gems','鑽石 ×50',25,{gems:50},5],['attack','攻擊靈藥',15,{consumables:{attack:1}},2],['hp','生命藥水 ×3',10,{consumables:{hp:3}},5],['materials','九種素材各 ×5',20,{materials:allMat(5)},3],['hourglass','加速沙漏',15,{consumables:{hourglass:1}},2],['fang','嗜血獠牙',80,{artifact:'fang'},1],['badge','傳說徽章碎片',30,{badges:1},1]].forEach(a=>add('event:'+a[0],a[1],'event',{points:a[2]},a[3],a[4],a[0]==='fang'&&e.artifacts.fang?'已解鎖此神器':''));
