  function shopAction(s,p){const count=p.count===undefined?1:Number(p.count);if(!Number.isInteger(count)||count<1||count>100)return fail('購買數量須為 1～100');let bought=0;for(let n=0;n<count;n++){const row=shops(s).find(x=>x.id===p.id);if(!row)return fail('不存在的商品');if(row.locked)return bought?ok('已購買 '+bought+' 份；'+row.reason,{count:bought}):fail(row.reason);const error=pay(s,row.cost);if(error)return bought?ok('已購買 '+bought+' 份',{count:bought}):error;const store=row.group==='general'?s.ext.claimed.once:row.group==='daily'?s.ext.daily.shop:s.ext.weekly.shop;store['shop:'+row.id]=num(store['shop:'+row.id])+1;reward(s,row.reward,row.name);bought++;}return ok('已購買 '+bought+' 份',{count:bought});}

  function visitorPrice(w){return Math.round((100+w.baseLevel*40)*RARITY[w.stars-1]*(1-.06*Math.floor(w.affinity/25)));}
  function spawnVisitor(s){
    if(s.ext.wanderers.length>=3+2*s.buildings.tavern)return;
    const weights=[Math.max(1,70-s.buildings.tavern*2),25+s.buildings.tavern,5+s.buildings.tavern],roll=rng(s)*weights.reduce((a,b)=>a+b,0);let t=0,v=roll;while(t<2&&v>=weights[t])v-=weights[t++];
    const cls=CLASS[Math.floor(rng(s)*6)],a=VISITORS.find(x=>x[1]===cls&&x[2]===t+1);let r=rng(s)*100,stars=1;for(const weight of [55,28,11,4.5,1.3,.2]){if(r<weight)break;r-=weight;stars++;}stars=Math.min(6,stars);
    const maxHp=80+a[3]*15;const w={id:uid(s,'visitor'),name:a[0],classId:cls,type:a[2],stars,baseLevel:a[3],level:a[3],xp:0,hp:maxHp,maxHp,mood:80,wallet:80+a[3]*15,affinity:0,status:'arriving',actionSeconds:0,ageSeconds:0,goldBase:a[4],materialRate:a[5],expedition:null};s.ext.wanderers.push(w);s.ext.wandererSeq++;log(s,w.name+' 抵達城門','visitor');
  }
  function expeditionGift(s,w,hours,z){const successChance=Math.min(.95,Math.max(.2,.78+.04*w.type+.02*Math.floor(w.affinity/25)-.035*(z-1)));return {chance:successChance,reward:{gold:Math.floor(w.goldBase*hours*8),materials:{[MAT[Math.min(8,z-1)]]:Math.max(1,Math.floor(hours*(1+.3*w.type)))}}};}
  function visitorAction(s,p,now){const w=s.ext.wanderers.find(w=>w.id===p.id);if(!w)return fail('流浪者已離開');if(p.action==='cancel'){if(!w.expedition)return fail('流浪者不在遠征中');w.expedition=null;w.status='resting';w.actionSeconds=0;return ok('遠征已取消，沒有發放獎勵');}if(w.expedition)return fail('遠征途中無法進行此操作');if(p.action==='feed'){if(s.ext.daily.feeding[w.id])return fail('今天已投餵此流浪者');const error=pay(s,{gold:Math.max(10,Math.ceil(visitorPrice(w)*.1))});if(error)return error;s.ext.daily.feeding[w.id]=true;w.affinity=Math.min(100,w.affinity+15);w.mood=Math.min(100,w.mood+10);return ok(w.name+' 的好感提升了');}if(p.action==='recruit'){if(s.heroes.length>=capacity(s))return fail('名冊已滿');const error=pay(s,{gold:visitorPrice(w)});if(error)return error;const h=C().makeHero(s,w.classId,w.stars,Math.min(200,w.baseLevel+Math.floor(w.xp/120)+Math.floor(w.affinity/25)));h.name=w.name;h.visitorIdentity=w.id;s.heroes.push(h);s.ext.wanderers=s.ext.wanderers.filter(v=>v.id!==w.id);s.stats.recruits=num(s.stats.recruits)+1;onEvent(s,'recruit',{hero:h});return ok(w.name+' 已加入名冊',{heroId:h.id});}if(p.action==='expedition'){const hours=Number(p.hours),z=Number(p.zone);if(![1,4,8].includes(hours)||!Number.isInteger(z)||z<1||z>zone(s))return fail('請選擇 1／4／8 小時及本輪已解鎖區域');if(w.mood<40)return fail('遠征需要心情至少 40');const plan=expeditionGift(s,w,hours,z);w.expedition={id:uid(s,'visitorTrip'),startAt:now,endAt:now+hours*HOUR,hours,zone:z,chance:plan.chance,reward:plan.reward};w.status='expedition';return ok(w.name+' 已出發遠征');}return fail('不支援的流浪者操作');}
  function settleVisitor(s,w,now){const x=w.expedition;if(!x||x.endAt>now)return false;const win=rng(s)<x.chance;const r=clone(x.reward);if(!win){r.gold=Math.floor(r.gold*.3);for(const k of Object.keys(r.materials))r.materials[k]=Math.floor(r.materials[k]*.3);}w.expedition=null;w.status='resting';w.xp+=x.hours*(win?60:20);w.level=Math.min(200,w.baseLevel+Math.floor(w.xp/120));w.affinity=Math.min(100,w.affinity+(win?8:3));w.hp=Math.max(1,w.hp*(win?.8:.3));reward(s,r,w.name+' 遠征'+(win?'成功':'歸返'));return true;}
