  function commissionRows(s,now){const rr=dailyRandom(s.gameplaySeed+':commission:'+s.ext.period.day);return COMMISSIONS.map(a=>{const quality=Math.floor(rr()*3),mult=[1,2,4][quality],required=Math.floor(Math.max(150,s.ext.daily.challengeBase)*[.5,.75,1.1][quality]*(a[2]===8?1.25:a[2]===4?1.1:1));const id=s.ext.period.day+':'+a[0],active=s.ext.commissions.find(c=>c.id===id);return {id,key:a[0],name:a[1],hours:a[2],preferredClass:a[3],quality:['普通','稀有','史詩'][quality],qualityIndex:quality,mult,requiredPower:required,reward:{gold:Math.floor(rate(s)*(a[2]===8?1.25:a[2]===4?1.1:1)*mult*.13),...(quality===2?{books:1,materials:{void:1}}:{})},active:active?clone(active):null,remainingSeconds:active?Math.max(0,Math.ceil((active.endAt-now)/1000)):0,used:!!s.ext.daily.commissionUsed[id],action:'commission',type:'commission',payload:{id,heroIds:[]},cost:{},locked:level(s)<16||!!s.ext.daily.commissionUsed[id],reason:level(s)<16?'王國 Lv16 解鎖':s.ext.daily.commissionUsed[id]?'本日此委託已使用':''};});}
