  const CHALLENGE_META=[['gold','黃金秘境',1,'zone',3],['xp','智慧秘境',3,'zone',3],['materials','豐饒秘境',5,'zone',3],['arena','十人競技場',1,'zone',5],['king','三隊王者競技',12,'kingdom',5],['labyrinth','奇境迷宮',14,'kingdom',0],['guildBoss','公會首領',1,'zone',3],['worldBoss','世界首領',1,'zone',3],['tower','元素挑戰塔',1,'zone',0]];
