  function blessingAction(s,p){const lab=s.ext.weekly.labyrinth;if(level(s)<14||!lab.pending)return fail('完成事件節點後才可選擇增益');const offers=lab.offers?.[0]||[];if(!offers.includes(p.id))return fail('請選擇本次提供的三種增益');if(num(lab.blessings[p.id])>=3)return fail('該增益已達三階；可選其他增益');lab.blessings[p.id]++;lab.pending--;lab.offers.shift();return ok('迷宮增益已提升；只在本週迷宮中生效');}
  function guildBonus(l){return .02*Math.min(10,l)+.01*Math.min(5,Math.max(0,l-10))+.005*Math.max(0,l-15);}
  function guildDonate(s,p){const d=s.ext.daily,g=s.ext.guild;if(g.level>=20)return fail('公會已滿級');if(p.feast&&d.feast)return fail('今日盛宴已舉行');if(!p.feast&&d.guildDonations>=3)return fail('今日捐獻次數已用完');const err=pay(s,{gold:p.feast?7500:1500});if(err)return err;if(p.feast)d.feast=true;else d.guildDonations++;g.xp+=(p.feast?160:40)*g.level;while(g.level<20&&g.xp>=200*g.level){g.xp-=200*g.level;g.level++;}return ok('捐獻完成，公會 Lv'+g.level);}
